def Partiziona(A, inizio, fine):
    pivot = A[inizio]
    i = inizio + 1
    j = fine
    while i <= j:
        if A[i] < pivot:
            i += 1
        elif A[j] >= pivot:
            j -= 1
        else:
            A[i], A[j] = A[j], A[i]
            i += 1
            j -= 1
    A[inizio], A[j] = A[j], A[inizio]
    return j

